let cachedApiKey = null;
function resolveInnertubeApiKey() {
  if (cachedApiKey) return cachedApiKey;
  const key = window.ytcfg?.get?.('INNERTUBE_API_KEY'); // O(1) global read
  if (typeof key === 'string' && key) { cachedApiKey = key; return key; }
  let t = '';
  for (const s of document.scripts) { if (!s.src) t += s.textContent + '\n'; }
  return cachedApiKey = extractInnertubeApiKey(t); // script-text only, memoized
}
// + single poll interval với pollDeadline được refresh mỗi nav trigger.
